'use strict';

// MODULES //

var min = require( '@stdlib/math/base/special/min' );
var floor = require( '@stdlib/math/base/special/floor' );
var dgelq2 = require( './dgelq2.js' );
var dlarfb = require( './dlarfb.js' );
var dlarft = require( './dlarft.js' );


// MAIN //

/**
* Compute a LQ factorization of a real M-by-N matrix `A`.
*
* ## Notes
*
* -   On exit, the elements on and below the diagonal of the array contain the `m-by-min(m,n)` lower trapezoidal matrix `L` (`L` is lower triangular if `m <= n`).
* -   On exit, the elements above the diagonal, with the array `TAU`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
* -   `LWORK >= 1`, if `MIN(M,N) = 0`, and `LWORK >= M`, otherwise. For optimum performance `LWORK >= M*NB`, where `NB` is the optimal blocksize.
* -   If `LWORK = -1`, then a workspace query is assumed; the routine only calculates the optimal size of the `WORK` array, returns this value as the first entry of the `WORK` array
*
* @private
* @param {NonNegativeInteger} M - number of rows in `A`
* @param {NonNegativeInteger} N - number of columns in `A`
* @param {Float64Array} A - input/output matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @param {Float64Array} TAU - output array of scalar factors (length `min(M,N)`)
* @param {integer} strideTAU - stride for TAU
* @param {NonNegativeInteger} offsetTAU - starting index for TAU
* @param {Float64Array} WORK - workspace array (length >= `M`)
* @param {integer} strideWORK - stride for `WORK`
* @param {NonNegativeInteger} offsetWORK - starting index for `WORK`
* @param {NonNegativeInteger} LWORK - dimension of the array `WORK`
* @returns {integer} status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
* var TAU = new Float64Array( 3 );
* var WORK = new Float64Array( 4 );
*
* dgelqf( 3, 4, A, 1, 3, 0, TAU, 1, 0, WORK, 1, 0, 4 );
* // A => <Float64Array>[ ~-5.477, ~-12.78, ~-20.083, ~0.309, ~-3.266, ~-6.532, ~0.463, ~-0.327, ~0.0, ~0.618, ~-0.789, ~0.618 ]
* // TAU => <Float64Array>[ ~1.183, ~1.156, ~1.447 ]
* // WORK => <Float64Array>[ 3.0, ~24.593, 0.0, 0.0 ]
*/
function dgelqf( M, N, A, strideA1, strideA2, offsetA, TAU, strideTAU, offsetTAU, WORK, strideWORK, offsetWORK, LWORK ) { // eslint-disable-line stdlib/jsdoc-doctest-decimal-point, max-len, max-params
	var ldwork;
	var lquery;
	var inctau;
	var lwkopt;
	var nbmin;
	var inca;
	var taui;
	var aii;
	var iws;
	var ib;
	var nb;
	var nx;
	var i;
	var k;

	k = min( M, N );
	nb = 32; // The optimal block size derived from fortran LAPACK call `ilaenv( 1, 'DGELQF', ' ', m, n, -1, -1 )`
	lquery = ( LWORK === -1 );

	if ( lquery ) {
		if ( k === 0 ) {
			lwkopt = 1;
		} else {
			lwkopt = M * nb;
		}
		WORK[ offsetWORK ] = lwkopt;
		return 0;
	}

	// Quick return if possible
	if ( k === 0 ) {
		WORK[ offsetWORK ] = 1;
		return 0;
	}

	nbmin = 2;
	nx = 0;
	iws = M;

	if ( nb > 1 && nb < k ) {
		// Determine when to cross over from blocked to unblocked code.
		nx = 128; // The crossover point derived from fortran LAPACK call `ilaenv( 3, 'DGELQF', ' ', m, n, -1, -1 )`

		if ( nx < k ) {
			// Determine if workspace is large enough for blocked code.
			ldwork = M;
			iws = ldwork * nb;
			if ( LWORK < iws ) {
				// Not enough workspace to use optimal NB: reduce NB and determine the minimum value of NB.
				nb = floor( LWORK / ldwork );
				nbmin = 2; // The minimal block size derived from fortran LAPACK call `ilaenv( 2, 'DGELQF', ' ', m, n, -1, -1 )`
			}
		}
	}

	inca = nb * ( strideA1 + strideA2 );
	inctau = nb * strideTAU;

	aii = offsetA; // Index of A(i,i)
	taui = offsetTAU; // Index of TAU(i)

	if ( nb >= nbmin && nb < k && nx < k ) {
		// Use blocked code initially
		for ( i = 0; i < k - nx; i += nb ) {
			ib = min( k - i, nb );

			// Compute the LQ factorization of the current block A(i:i+ib-1,i:n)
			dgelq2( ib, N - i, A, strideA1, strideA2, aii, TAU, strideTAU, taui, WORK, strideWORK, offsetWORK );

			if ( i + ib < M ) {
				// Form the triangular factor of the block reflector: H = H(i) H(i+1) . . . H(i+ib-1)
				dlarft( 'forward', 'rows', N - i, ib, A, strideA1, strideA2, aii, TAU, strideTAU, taui, WORK, 1, ldwork, offsetWORK );

				// Apply H to A(i+ib:m,i:n) from the right
				dlarfb( 'right', 'no-transpose', 'forward', 'rows', M - i - ib, N - i, ib, A, strideA1, strideA2, aii, WORK, 1, ldwork, offsetWORK, A, strideA1, strideA2, aii + ( ib * strideA1 ), WORK, 1, ldwork, offsetWORK + ( ib * strideWORK ) );
			}

			aii += inca;
			taui += inctau;
		}
	} else {
		i = 0;
	}

	// Use unblocked code to factor the last or only block
	if ( i <= k - 1 ) {
		dgelq2( M - i, N - i, A, strideA1, strideA2, aii, TAU, strideTAU, taui, WORK, strideWORK, offsetWORK );
	}

	WORK[ offsetWORK ] = iws;

	return 0;
}


// EXPORTS //

module.exports = dgelqf;
